package pe.com.dentalamericana.booking.dto;import jakarta.validation.constraints.*;import pe.com.dentalamericana.booking.BookingRequestStatus;import java.time.*;public final class BookingDtos{private BookingDtos(){}public record PublicBookingRequestDto(@NotBlank@Size(max=150)String fullName,@Size(max=20)String documentNumber,@NotBlank@Pattern(regexp="^[0-9+ ()-]{7,20}$")String mobile,@Email@Size(max=150)String email,@NotBlank@Size(max=120)String service,@FutureOrPresent LocalDate preferredDate,@Pattern(regexp="^(MANANA|TARDE|INDIFERENTE)$")String preferredShift,@Size(max=800)String message,@AssertTrue(message="Debe aceptar el tratamiento de datos para solicitar contacto")boolean privacyConsent){}public record ManageBookingRequest(@NotNull BookingRequestStatus status,@Size(max=500)String observation,Long appointmentId,@NotNull Long version){}public record BookingResponse(Long id,String fullName,String documentNumber,String mobile,String email,String service,LocalDate preferredDate,String preferredShift,String message,BookingRequestStatus status,String internalObservation,Long appointmentId,Long attendedBy,Instant createdAt,Instant updatedAt,Long version){}
}
